/**
 * Custom authorization UI for Supabase's OAuth 2.1 server.
 *
 * Supabase hosts /authorize, /token, /register, and .well-known discovery on
 * its own infrastructure. You configure a consent-screen URL in the dashboard
 * (Authentication → OAuth Server) — when a user needs to approve an OAuth
 * client, Supabase redirects their browser here with `?authorization_id=<uuid>`.
 *
 * Routes:
 *   GET  /auth/consent?authorization_id=<id>
 *        Renders the sign-in page if the visitor has no session, otherwise
 *        fetches the authorization details from Supabase and renders consent.
 *   GET  /auth/signin/:provider?authorization_id=<id>
 *        Kicks off a Supabase social sign-in (Google or GitHub). Supabase
 *        issues the authorize URL and we 302 to it; PKCE state is stored
 *        in cookies by @supabase/ssr.
 *   GET  /auth/callback?code=<code>&authorization_id=<id>
 *        Exchange point after the user returns from Google/GitHub. The
 *        code is swapped for a session, the session is written to cookies,
 *        and we redirect back to /auth/consent.
 *   POST /auth/consent?authorization_id=<id>
 *        Body: { approve: boolean }
 *        Forwards the decision to Supabase, which responds with a redirect_url
 *        pointing back to the MCP client.
 *
 * Enable the Google and GitHub providers in the Supabase Dashboard
 * (Authentication → Providers) and add `<SITE_URL>/auth/callback` to the
 * allowed redirect URLs.
 *
 * Docs: https://supabase.com/docs/guides/auth/oauth-server
 */

import type { MCPServer } from "mcp-use/server";
import { createServerClient } from "@supabase/ssr";
import type { SupabaseClient } from "@supabase/supabase-js";
import { getCookie, setCookie } from "hono/cookie";
import type { Context } from "hono";

import { renderConsentPage, renderSignInPage } from "./views/index.js";
import { safeJson } from "./render.js";

export interface MountAuthRoutesOptions {
  projectId: string;
  publishableKey: string;
  /**
   * Absolute URL the browser uses to reach this server (no trailing slash).
   * Used to build the OAuth callback URL. Defaults to the request origin,
   * which is fine for local dev but may be wrong behind proxies — set
   * MCP_USE_OAUTH_SUPABASE_SITE_URL in production.
   */
  siteUrl?: string;
}

type Provider = "google" | "github";
const PROVIDERS: Provider[] = ["google", "github"];

function supabaseProjectUrl(projectId: string): string {
  return `https://${projectId}.supabase.co`;
}

function getSupabaseClient(
  c: Context,
  url: string,
  key: string,
): SupabaseClient {
  return createServerClient(url, key, {
    cookies: {
      getAll() {
        const all = getCookie(c);
        return Object.entries(all).map(([name, value]) => ({ name, value }));
      },
      setAll(cookiesToSet) {
        for (const { name, value, options } of cookiesToSet) {
          setCookie(c, name, value, options as Parameters<typeof setCookie>[3]);
        }
      },
    },
  });
}

function originFromRequest(c: Context, override: string | undefined): string {
  if (override) return override.replace(/\/$/, "");
  return new URL(c.req.url).origin;
}

export function mountAuthRoutes(
  server: MCPServer,
  { projectId, publishableKey, siteUrl }: MountAuthRoutesOptions,
): void {
  const supabaseUrl = supabaseProjectUrl(projectId);

  // -------------------------------------------------------------------------
  // GET /auth/consent?authorization_id=<id>
  //
  // This is the URL to configure as the consent screen in the Supabase
  // dashboard. Supabase redirects the browser here with only
  // `authorization_id`. If the user has no session we render sign-in;
  // otherwise we fetch the authorization details and render consent.
  // -------------------------------------------------------------------------
  server.app.get("/auth/consent", async (c) => {
    console.log("[auth-routes] GET /auth/consent hit:", new URL(c.req.url).search);
    const authorizationId = new URL(c.req.url).searchParams.get(
      "authorization_id",
    );
    if (!authorizationId) {
      return c.text("Missing authorization_id", 400);
    }

    const supabase = getSupabaseClient(c, supabaseUrl, publishableKey);
    const {
      data: { session },
    } = await supabase.auth.getSession();

    if (!session) {
      const providerHrefs = {
        google: `/auth/signin/google?authorization_id=${encodeURIComponent(authorizationId)}`,
        github: `/auth/signin/github?authorization_id=${encodeURIComponent(authorizationId)}`,
      };
      return c.html(renderSignInPage({ providerHrefs }));
    }

    const { data, error } = await supabase.auth.oauth.getAuthorizationDetails(
      authorizationId,
    );

    if (error || !data) {
      return c.text(
        `Failed to fetch authorization details: ${error?.message ?? "unknown error"}`,
        500,
      );
    }

    // If the user has already consented to these scopes, Supabase short-
    // circuits and returns a redirect URL — honor it immediately.
    if ("redirect_url" in data) {
      return c.redirect(data.redirect_url as string, 302);
    }

    const clientName =
      (data as { client?: { name?: string } }).client?.name || "the application";
    const clientUri =
      (data as { client?: { uri?: string | null } }).client?.uri ?? null;
    const rawScope = (data as { scope?: string }).scope || "";
    const scopes = rawScope ? rawScope.split(" ").filter(Boolean) : [];

    const consentScript = `
(function () {
  const AUTH_ID = ${safeJson(authorizationId)};
  const buttons = document.querySelectorAll('[data-consent]');
  buttons.forEach(function (btn) {
    btn.addEventListener('click', async function () {
      buttons.forEach(function (b) { b.disabled = true; });
      try {
        const res = await fetch('/auth/consent?authorization_id=' + encodeURIComponent(AUTH_ID), {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ approve: btn.dataset.consent === 'approve' }),
        });
        const data = await res.json();
        if (data && data.redirect_url) { window.location.href = data.redirect_url; return; }
        throw new Error((data && data.error) || 'Consent failed');
      } catch (err) {
        buttons.forEach(function (b) { b.disabled = false; });
        const msg = document.getElementById('consent-error');
        if (msg) msg.textContent = String((err && err.message) || err);
      }
    });
  });
})();
`;

    return c.html(
      renderConsentPage({ clientName, clientUri, scopes, consentScript }),
    );
  });

  // -------------------------------------------------------------------------
  // GET /auth/signin/:provider?authorization_id=<id>
  // Starts a Supabase social OAuth flow. The returned URL redirects the
  // browser to the provider (Google/GitHub); PKCE state is set by
  // @supabase/ssr via cookies on this response.
  // -------------------------------------------------------------------------
  server.app.get("/auth/signin/:provider", async (c) => {
    console.log("[auth-routes] /auth/signin hit:", c.req.param("provider"));
    const provider = c.req.param("provider") as Provider;
    if (!PROVIDERS.includes(provider)) {
      return c.text(`Unsupported provider: ${provider}`, 400);
    }

    const authorizationId = new URL(c.req.url).searchParams.get(
      "authorization_id",
    );
    if (!authorizationId) {
      return c.text("Missing authorization_id", 400);
    }

    const origin = originFromRequest(c, siteUrl);
    const callbackUrl = `${origin}/auth/callback?authorization_id=${encodeURIComponent(authorizationId)}`;

    const supabase = getSupabaseClient(c, supabaseUrl, publishableKey);
    const { data, error } = await supabase.auth.signInWithOAuth({
      provider,
      options: {
        redirectTo: callbackUrl,
        skipBrowserRedirect: true,
      },
    });

    if (error || !data?.url) {
      return c.text(
        `Failed to start ${provider} sign-in: ${error?.message ?? "no URL returned"}. ` +
          `Make sure the ${provider} provider is enabled in the Supabase dashboard.`,
        500,
      );
    }

    return c.redirect(data.url, 302);
  });

  // -------------------------------------------------------------------------
  // GET /auth/callback?code=<code>&authorization_id=<id>
  // Exchange the code for a session. @supabase/ssr writes the session
  // cookies automatically through our cookie adapter.
  // -------------------------------------------------------------------------
  server.app.get("/auth/callback", async (c) => {
    const url = new URL(c.req.url);
    console.log("[auth-routes] /auth/callback hit:", url.search);
    const code = url.searchParams.get("code");
    const authorizationId = url.searchParams.get("authorization_id");
    const providerError = url.searchParams.get("error_description");

    if (providerError) {
      return c.text(`Provider error: ${providerError}`, 400);
    }
    if (!code || !authorizationId) {
      return c.text("Missing code or authorization_id", 400);
    }

    const supabase = getSupabaseClient(c, supabaseUrl, publishableKey);
    const { error } = await supabase.auth.exchangeCodeForSession(code);

    if (error) {
      return c.text(`Sign-in failed: ${error.message}`, 500);
    }

    return c.redirect(
      `/auth/consent?authorization_id=${encodeURIComponent(authorizationId)}`,
      302,
    );
  });

  // -------------------------------------------------------------------------
  // POST /auth/consent?authorization_id=<id>
  //   body: { approve: boolean }
  // Forwards the decision to Supabase, which responds with a redirect_url
  // pointing back to the MCP client (with `code` & `state`, or an error).
  // -------------------------------------------------------------------------
  server.app.post("/auth/consent", async (c) => {
    const authorizationId = new URL(c.req.url).searchParams.get(
      "authorization_id",
    );
    if (!authorizationId) {
      return c.json({ error: "Missing authorization_id" }, 400);
    }

    const { approve } = await c.req.json<{ approve: boolean }>();
    const supabase = getSupabaseClient(c, supabaseUrl, publishableKey);
    const {
      data: { session },
    } = await supabase.auth.getSession();

    if (!session) {
      return c.json({ error: "not_authenticated" }, 401);
    }

    // `skipBrowserRedirect: true` keeps the SDK from trying to redirect the
    // (nonexistent) browser window on the server — we hand the URL back to
    // the client-side consent page, which performs the navigation.
    const { data, error } = approve
      ? await supabase.auth.oauth.approveAuthorization(authorizationId, {
          skipBrowserRedirect: true,
        })
      : await supabase.auth.oauth.denyAuthorization(authorizationId, {
          skipBrowserRedirect: true,
        });

    if (error || !data) {
      return c.json({ error: error?.message ?? "Consent failed" }, 500);
    }

    return c.json({ redirect_url: (data as { redirect_url: string }).redirect_url });
  });
}

/**
 * Supabase OAuth MCP Server
 *
 * Uses Supabase's OAuth 2.1 server — Supabase hosts /authorize, /token,
 * /register and .well-known discovery, while this example hosts the consent
 * screen (which also triggers sign-in for unauthenticated users). Configure
 * the consent URL in the Supabase Dashboard (Authentication → OAuth Server)
 * to point at /auth/consent here.
 *
 * Google and GitHub social login are wired up by default. Enable either
 * provider in the Supabase Dashboard under Auth → Providers and add the
 * OAuth callback URL `<SITE_URL>/auth/callback` to the allowed redirects.
 *
 * Token verification is automatic: new Supabase projects sign tokens with
 * ES256 and publish a JWKS endpoint, which the provider fetches and caches.
 * No JWT secret configuration is required.
 *
 * Docs: https://supabase.com/docs/guides/auth/oauth-server
 *
 * Environment variables:
 * - MCP_USE_OAUTH_SUPABASE_PROJECT_ID       (required)
 * - MCP_USE_OAUTH_SUPABASE_PUBLISHABLE_KEY  (required — used by the consent UI
 *                                            and by tools calling Supabase)
 * - MCP_USE_OAUTH_SUPABASE_SITE_URL         (optional; defaults to the request
 *                                            origin — set for production/proxies)
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  MCPServer,
  oauthSupabaseProvider,
  error,
  object,
} from "mcp-use/server";
import { createClient } from "@supabase/supabase-js";

import { mountAuthRoutes } from "./auth-routes.js";

declare const process: {
  env: Record<string, string | undefined>;
  cwd(): string;
};

const SUPABASE_PROJECT_ID =
  process.env.MCP_USE_OAUTH_SUPABASE_PROJECT_ID ?? "";
const SUPABASE_PUBLISHABLE_KEY =
  process.env.MCP_USE_OAUTH_SUPABASE_PUBLISHABLE_KEY ?? "";
const SITE_URL = process.env.MCP_USE_OAUTH_SUPABASE_SITE_URL;

if (!SUPABASE_PROJECT_ID) {
  console.warn(
    "Warning: MCP_USE_OAUTH_SUPABASE_PROJECT_ID is not set — set it before using the server.",
  );
}
if (!SUPABASE_PUBLISHABLE_KEY) {
  console.warn(
    "Warning: MCP_USE_OAUTH_SUPABASE_PUBLISHABLE_KEY is not set — set it before using the server.",
  );
}

const supabaseUrl = `https://${SUPABASE_PROJECT_ID}.supabase.co`;

const server = new MCPServer({
  name: "mcp-oauth-supabase",
  version: "1.0.0",
  description: "MCP server with Supabase OAuth authentication",
  oauth: oauthSupabaseProvider({ projectId: SUPABASE_PROJECT_ID }),
});

// ---------------------------------------------------------------------------
// Serve the compiled Tailwind stylesheet
// ---------------------------------------------------------------------------

const stylesCss = readFileSync(
  join(process.cwd(), "public", "styles.css"),
  "utf-8",
);

server.app.get("/styles.css", () => {
  return new Response(stylesCss, {
    status: 200,
    headers: {
      "Content-Type": "text/css; charset=utf-8",
      "Cache-Control": "public, max-age=3600",
    },
  });
});

// Mount the consent + sign-in pages that Supabase redirects to after /authorize.
mountAuthRoutes(server, {
  projectId: SUPABASE_PROJECT_ID,
  publishableKey: SUPABASE_PUBLISHABLE_KEY,
  siteUrl: SITE_URL,
});

server.tool(
  {
    name: "get-user-info",
    description: "Get information about the authenticated user",
  },
  async (_args, ctx) =>
    object({
      userId: ctx.auth.user.userId,
      email: ctx.auth.user.email,
    }),
);

server.tool(
  {
    name: "list-notes",
    description:
      "Fetch the user's notes from Supabase using their access token",
  },
  async (_args, ctx) => {
    const supabase = createClient(supabaseUrl, SUPABASE_PUBLISHABLE_KEY, {
      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
      global: {
        headers: { Authorization: `Bearer ${ctx.auth.accessToken}` },
      },
    });

    const { data, error: queryError } = await supabase.from("notes").select();

    if (queryError) {
      return error(`Failed to fetch notes: ${queryError.message}`);
    }

    return object({ notes: data ?? [] });
  },
);

server.listen().then(() => {
  console.log("Supabase OAuth MCP Server Running");
});

import type { ReactElement } from "react";
import { renderToString } from "react-dom/server";

export function renderPage(element: ReactElement): string {
  return "<!DOCTYPE html>" + renderToString(element);
}

/**
 * JSON.stringify a value for safe interpolation into an inline <script>.
 * Escapes characters that could terminate the script tag (e.g. `</script>`)
 * or be read as HTML entities by the browser parser.
 */
export function safeJson(value: unknown): string {
  return JSON.stringify(value)
    .replace(/</g, "\\u003c")
    .replace(/>/g, "\\u003e")
    .replace(/&/g, "\\u0026");
}

import { buttonVariants } from "../components/ui/button.js";
import { Icons } from "../components/ui/icons.js";
import { cn } from "../lib/utils.js";
import { Layout } from "./layout.js";

interface SignInProps {
  /**
   * Map from provider id (e.g. "google", "github") to the href the button
   * navigates to when clicked. The server builds these from the current
   * authorization_id so the OAuth flow can resume after sign-in.
   */
  providerHrefs: {
    google: string;
    github: string;
  };
  errorMessage?: string;
}

export function SignIn({ providerHrefs, errorMessage }: SignInProps) {
  const linkClass = cn(
    buttonVariants({ variant: "outline", size: "lg" }),
    "w-full",
  );

  return (
    <Layout title="Sign In">
      <main className="flex min-h-screen items-center justify-center px-4 py-8">
        <div className="mx-auto w-full max-w-[400px] space-y-8">
          <div className="space-y-2 text-center">
            <h1 className="text-3xl font-medium tracking-tight">
              Sign in to continue
            </h1>
            <p className="text-sm text-muted-foreground">
              Authorize the MCP client to access your account.
            </p>
          </div>

          <div className="space-y-3">
            <a href={providerHrefs.google} className={linkClass}>
              <Icons.google className="h-4 w-4" />
              Continue with Google
            </a>
            <a href={providerHrefs.github} className={linkClass}>
              <Icons.github className="h-4 w-4" />
              Continue with GitHub
            </a>
          </div>

          {errorMessage ? (
            <p className="text-center text-sm text-destructive">
              {errorMessage}
            </p>
          ) : null}
        </div>
      </main>
    </Layout>
  );
}

import type { ReactNode } from "react";

interface LayoutProps {
  title: string;
  children: ReactNode;
}

export function Layout({ title, children }: LayoutProps) {
  return (
    <html lang="en">
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <title>{title}</title>
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link
          rel="preconnect"
          href="https://fonts.gstatic.com"
          crossOrigin="anonymous"
        />
        <link
          rel="stylesheet"
          href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;700&display=swap"
        />
        <link rel="stylesheet" href="/styles.css" />
      </head>
      <body>{children}</body>
    </html>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { renderPage } from "../render.js";
import { Consent } from "./consent.js";
import { SignIn } from "./sign-in.js";

export function renderSignInPage(opts: {
  providerHrefs: { google: string; github: string };
  errorMessage?: string;
}): string {
  return renderPage(<SignIn {...opts} />);
}

export function renderConsentPage(opts: {
  clientName: string;
  clientUri?: string | null;
  scopes: string[];
  consentScript: string;
}): string {
  return renderPage(<Consent {...opts} />);
}

import { cva, type VariantProps } from "class-variance-authority";
import * as React from "react";

import { cn } from "../../lib/utils.js";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-full text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        outline:
          "border border-input bg-background shadow-xs hover:bg-accent hover:text-accent-foreground",
        secondary:
          "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
      },
      size: {
        default: "h-10 px-4 py-2",
        sm: "h-9 px-3",
        lg: "h-11 px-8",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, ...props }, ref) => (
    <button
      className={cn(buttonVariants({ variant, size, className }))}
      ref={ref}
      {...props}
    />
  ),
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { cva, type VariantProps } from "class-variance-authority";
import * as React from "react";

import { cn } from "../../lib/utils.js";

const alertVariants = cva(
  "relative w-full rounded-lg border px-4 py-3 text-sm grid has-[>svg]:grid-cols-[calc(var(--spacing)*4)_1fr] grid-cols-[0_1fr] has-[>svg]:gap-x-3 gap-y-0.5 items-start [&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current",
  {
    variants: {
      variant: {
        default: "bg-card text-card-foreground",
        destructive:
          "text-red-700 border-none dark:text-red-300 bg-red-500/10 [&>svg]:text-current *:data-[slot=alert-description]:text-red-700",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

function Alert({
  className,
  variant,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof alertVariants>) {
  return (
    <div
      data-slot="alert"
      role="alert"
      className={cn(alertVariants({ variant }), className)}
      {...props}
    />
  );
}

function AlertDescription({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-description"
      className={cn(
        "text-muted-foreground col-start-2 grid justify-items-start gap-1 text-sm [&_p]:leading-relaxed",
        className,
      )}
      {...props}
    />
  );
}

export { Alert, AlertDescription };
